/* H1 S0 v1: ONE creation day 2026-06-01; event enumeration, NO returns. Rendered by build_h1_s0.py render_v1. */ /* v1 vs v0: no solana.transactions join (run V_failed_evt_check first); IF() instead of FILTER in OVER(); */ /* numeric-seconds RANGE; is_mayhem flag; case fixture mints always output (compare h1_s0_fixture_expected.csv). */ /* DRAFT: not executed on Dune. First validate table/column binding and fixtures. */ /* Scan partitions: 2026-06-01 .. 2026-06-03; per-mint end = created_at + 1470 minutes. */ /* There is NO SQL credit stop. Set/verify the platform per-execution cost cap. */ /* Amounts are lamports: curve sol_amount; AMM quote_amount_in_with_lp_fee. */ /* The latter was checked against cached raw BuyEvents and pool balance deltas. */ /* Deposit/Withdraw decoded-table availability still needs Dune binding validation. */ /* Success filtering relies on decoded event tables excluding failed txs (F60 + V_failed_evt_check). */ /* Pool scope: pump curve + pump-created index=0 PumpSwap pools, not every venue. */ /* One heavy events -> txs -> windows -> per_coin chain; no returns/30d scan. */ WITH mayhem AS (SELECT mint, BOOL_OR(CAST(COALESCE(CAST(is_mayhem_mode AS TEXT) IN ('true', '1'), FALSE) AS BOOLEAN)) AS is_mayhem FROM pumpdotfun_solana.pump_evt_createevent WHERE evt_block_date = CAST('2026-06-01' AS DATE) GROUP BY 1), cohort AS (SELECT e.mint, MIN(e.evt_block_time) AS created_at FROM pumpdotfun_solana.pump_evt_createevent AS e WHERE e.evt_block_date = CAST('2026-06-01' AS DATE) GROUP BY 1), creation_mints AS (/* This small lookup deliberately includes all quotes. Successful creation */ /* and SOL scope are established below from decoded creation events. */ SELECT mint, created_at FROM cohort), pools AS (SELECT pool, base_mint AS mint FROM pumpdotfun_solana.pump_amm_evt_createpoolevent WHERE evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-06-03' AS DATE) AND base_mint IN (SELECT mint FROM creation_mints) AND evt_outer_executing_account = '6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P' AND index = 0 GROUP BY 1, 2), events AS (SELECT mint, evt_block_time AS ts, evt_block_slot AS slot, evt_tx_index AS txi, evt_tx_id AS sig, 'curve' AS venue, CAST("user" AS TEXT) AS actor, CASE WHEN COALESCE(is_buy, isBuy) THEN TRY_CAST(COALESCE(sol_amount, solAmount) AS BIGINT) ELSE CAST('0' AS BIGINT) END AS buy_lamports, CASE WHEN COALESCE(is_buy, isBuy) THEN 0 ELSE 1 END AS sells, 0 AS special, CASE WHEN COALESCE(is_buy, isBuy) IS NULL THEN 1 ELSE 0 END AS missing_direction FROM pumpdotfun_solana.pump_evt_tradeevent WHERE evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-06-03' AS DATE) AND mint IN (SELECT mint FROM creation_mints) UNION ALL SELECT p.mint, e.evt_block_time, e.evt_block_slot, e.evt_tx_index, e.evt_tx_id, 'pool', CAST(e."user" AS TEXT), TRY_CAST(e.quote_amount_in_with_lp_fee AS BIGINT), 0, 0, 0 FROM pumpdotfun_solana.pump_amm_evt_buyevent AS e JOIN pools AS p ON p.pool = e.pool WHERE e.evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-06-03' AS DATE) UNION ALL SELECT p.mint, e.evt_block_time, e.evt_block_slot, e.evt_tx_index, e.evt_tx_id, 'pool', CAST(e."user" AS TEXT), CAST('0' AS BIGINT), 1, 0, 0 FROM pumpdotfun_solana.pump_amm_evt_sellevent AS e JOIN pools AS p ON p.pool = e.pool WHERE e.evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-06-03' AS DATE) UNION ALL SELECT p.mint, e.evt_block_time, e.evt_block_slot, e.evt_tx_index, e.evt_tx_id, 'pool', CAST(NULL AS TEXT), CAST('0' AS BIGINT), 0, 1, 0 FROM pumpdotfun_solana.pump_amm_evt_depositevent AS e JOIN pools AS p ON p.pool = e.pool WHERE e.evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-06-03' AS DATE) UNION ALL SELECT p.mint, e.evt_block_time, e.evt_block_slot, e.evt_tx_index, e.evt_tx_id, 'pool', CAST(NULL AS TEXT), CAST('0' AS BIGINT), 0, 1, 0 FROM pumpdotfun_solana.pump_amm_evt_withdrawevent AS e JOIN pools AS p ON p.pool = e.pool WHERE e.evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-06-03' AS DATE) UNION ALL SELECT mint, evt_block_time, evt_block_slot, evt_tx_index, evt_tx_id, 'migration', CAST(NULL AS TEXT), CAST('0' AS BIGINT), 0, 1, 0 FROM pumpdotfun_solana.pump_evt_completepumpammmigrationevent WHERE evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-06-03' AS DATE) AND mint IN (SELECT mint FROM creation_mints) UNION ALL SELECT base_mint, evt_block_time, evt_block_slot, evt_tx_index, evt_tx_id, 'pool_create', CAST(NULL AS TEXT), CAST('0' AS BIGINT), 0, 1, 0 FROM pumpdotfun_solana.pump_amm_evt_createpoolevent WHERE evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-06-03' AS DATE) AND pool IN (SELECT pool FROM pools) UNION ALL SELECT mint, evt_block_time, evt_block_slot, evt_tx_index, evt_tx_id, CASE WHEN quote_mint IS NULL OR quote_mint = '11111111111111111111111111111111' THEN 'creation_sol' ELSE 'creation_other' END, CAST(NULL AS TEXT), CAST('0' AS BIGINT), 0, 1, 0 FROM pumpdotfun_solana.pump_evt_createevent WHERE evt_block_date = CAST('2026-06-01' AS DATE)), txs AS (SELECT e.mint, e.sig, MAX(e.ts) AS ts, MAX(e.slot) AS slot, MAX(e.txi) AS txi, SUM(COALESCE(e.buy_lamports, CAST('0' AS BIGINT))) AS buy_lamports, SUM(e.sells) AS sells, SUM(e.special) AS special, COUNT_IF(e.buy_lamports IS NULL OR e.buy_lamports < 0 OR e.missing_direction > 0 OR e.slot IS NULL OR e.txi IS NULL OR e.sig IS NULL) AS bad_rows, COUNT(DISTINCT e.venue) AS venue_count, BOOL_OR(CAST(e.venue IN ('creation_sol', 'creation_other') AS BOOLEAN)) AS is_create, BOOL_OR(CAST(e.venue = 'creation_sol' AS BOOLEAN)) AS is_sol_create, ARRAY_TO_STRING(ARRAY_SORT(LIST_DISTINCT(ARRAY_AGG(e.venue))), ',') AS venues, ARRAY_TO_STRING(ARRAY_SORT(LIST_DISTINCT(ARRAY_AGG(e.actor) FILTER(WHERE e.buy_lamports > 0))), ',') AS actors FROM events AS e GROUP BY 1, 2), dated AS (SELECT *, MIN(CASE WHEN is_create THEN ts END) OVER (PARTITION BY mint) AS created_at, BOOL_OR(CAST(is_sol_create AS BOOLEAN)) OVER (PARTITION BY mint) AS is_sol FROM txs), monitored AS (SELECT * FROM dated WHERE NOT created_at IS NULL AND ts >= created_at AND ts < created_at + INTERVAL '1470' MINUTE), sequenced AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY mint ORDER BY slot, txi, sig) AS seq, MAX(ts) OVER (PARTITION BY mint ORDER BY slot, txi, sig ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS clock_ts FROM monitored), clock_checked AS (SELECT *, bad_rows + CASE WHEN ts <> clock_ts THEN 1 ELSE 0 END AS bad_clock_rows, EPOCH(clock_ts) AS clock_s FROM sequenced), windowed AS (/* A monotone prefix clock prevents a later slot with a regressed blockTime */ /* leaking into an earlier event's RANGE window. Regressed rows are flagged. */ SELECT *, SUM(buy_lamports) OVER (PARTITION BY mint ORDER BY clock_s RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) - SUM(buy_lamports) OVER (PARTITION BY mint, clock_s ORDER BY slot, txi, sig ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS pre30_buy_lamports, SUM(bad_clock_rows) OVER (PARTITION BY mint ORDER BY clock_s RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) - SUM(bad_clock_rows) OVER (PARTITION BY mint, clock_s ORDER BY slot, txi, sig ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS pre30_bad_rows FROM clock_checked), marked AS (SELECT *, is_sol AND ts >= created_at + INTERVAL '30' MINUTE AND buy_lamports >= CAST('4000000000' AS BIGINT) AND pre30_buy_lamports < CAST('4000000000' AS BIGINT) AND bad_clock_rows = 0 AND pre30_bad_rows = 0 AND sells = 0 AND special = 0 AND venue_count = 1 AS eligible FROM windowed), per_coin AS (SELECT mint, MIN(created_at) AS created_at, BOOL_OR(CAST(is_sol AS BOOLEAN)) AS is_sol, COUNT_IF(buy_lamports > 0 OR sells > 0) AS n_decoded_txs, COUNT_IF(bad_clock_rows > 0) AS n_bad_txs, COUNT_IF(ts >= created_at + INTERVAL '30' MINUTE AND buy_lamports >= CAST('4000000000' AS BIGINT) AND (sells > 0 OR special > 0 OR venue_count <> 1)) AS n_large_mixed_txs, COUNT_IF(eligible) AS n_eligible_txs, ARG_MIN(ts, seq) FILTER(WHERE eligible) AS signal_time, ARG_MIN(slot, seq) FILTER(WHERE eligible) AS signal_slot, ARG_MIN(txi, seq) FILTER(WHERE eligible) AS signal_tx_index, ARG_MIN(sig, seq) FILTER(WHERE eligible) AS signal_signature, ARG_MIN(venues, seq) FILTER(WHERE eligible) AS signal_venue, ARG_MIN(actors, seq) FILTER(WHERE eligible) AS signal_actors, ARG_MIN(buy_lamports, seq) FILTER(WHERE eligible) AS signal_buy_lamports, ARG_MIN(pre30_buy_lamports, seq) FILTER(WHERE eligible) AS signal_pre30_lamports FROM marked GROUP BY 1), joined AS (SELECT p.mint, p.created_at, p.is_sol, p.n_decoded_txs, p.n_bad_txs, p.n_large_mixed_txs, p.n_eligible_txs, p.signal_time, p.signal_slot, p.signal_tx_index, p.signal_signature, p.signal_venue, p.signal_actors, p.signal_buy_lamports, p.signal_pre30_lamports, COALESCE(m.is_mayhem, FALSE) AS is_mayhem FROM per_coin AS p LEFT JOIN mayhem AS m ON m.mint = p.mint) SELECT CASE WHEN GROUPING(mint) = 1 THEN '__SUMMARY__' ELSE mint END AS mint, CASE WHEN GROUPING(mint) = 1 THEN 'summary' ELSE CASE WHEN MAX(n_eligible_txs) > 0 THEN CASE WHEN MAX(n_bad_txs) > 0 THEN 'candidate_needs_data_review' ELSE 'candidate' END ELSE CASE WHEN MAX(n_bad_txs) > 0 THEN 'data_quality' ELSE 'fixture' END END END AS row_type, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(is_mayhem) END AS is_mayhem, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(created_at) END AS created_at, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(signal_time) END AS signal_time, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(signal_slot) END AS signal_slot, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(signal_tx_index) END AS signal_tx_index, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(signal_signature) END AS signal_signature, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(signal_venue) END AS signal_venue, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(signal_actors) END AS signal_actors, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(signal_buy_lamports) END AS signal_buy_lamports, CASE WHEN GROUPING(mint) = 0 THEN ANY_VALUE(signal_pre30_lamports) END AS signal_pre30_lamports, COUNT(*) AS n_created, COUNT_IF(is_sol) AS n_sol_created, COUNT_IF(is_sol AND COALESCE(n_decoded_txs, 0) = 0) AS n_sol_without_decoded_events, COUNT_IF(n_eligible_txs > 0) AS n_triggered_coins, SUM(COALESCE(n_eligible_txs, 0)) AS n_eligible_txs, SUM(COALESCE(n_decoded_txs, 0)) AS n_decoded_txs, COUNT_IF(n_eligible_txs > 0 AND is_mayhem) AS n_triggered_mayhem, SUM(COALESCE(n_bad_txs, 0)) AS n_bad_txs, SUM(COALESCE(n_large_mixed_txs, 0)) AS n_large_mixed_txs FROM joined GROUP BY GROUPING SETS ((mint), ()) HAVING GROUPING(mint) = 1 OR MAX(n_eligible_txs) > 0 OR MAX(n_bad_txs) > 0 OR mint IN ('B1C2xfcUajAAU8n3zfuXqXvvALRw8cB5sPzNB5ktpump', 'YxUstMyYDyqPNz78auhYfhdUKrBQgg7uctnKNDEpump') ORDER BY row_type DESC, signal_time, mint
